head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.SECUGRP_ID_EN = "EN";             // 증권그룹 ETN (원본 SECUGRP_ID_EN — pcc glb 에 없어 화면 상수, 선례 ULDSTF08305)
scwin.SECUGRP_NM_EN = "ETN";            // 증권그룹명 (원본 fn_getSecuGrpNm(SECUGRP_ID_EN) — pcc getSecuGrpNm 에 EN 없음)
scwin.SEARCH_TP_ISU = "1";              // 조회 구분 — 종목 (원본 rdo_ISUR_CD_1.CodeValue == "1")
scwin.SEARCH_TP_ISUR = "2";             // 조회 구분 — 발행회사 (원본 rdo_ISUR_CD_2.CodeValue == "1")
scwin.SEL_TP_ISU = "1";                 // 팝업 선택 구분 — 종목 (원본 arrPar[7])
scwin.SEL_TP_ISUR = "2";                // 팝업 선택 구분 — 발행회사
scwin.SEL_TP_ALL = "3";                 // 팝업 선택 구분 — 전체
scwin.LIST_STAT_DELISTED = "D";         // 상장상태 — 상장폐지(삭제 종목)
scwin.POPUP_URL_REG = "/ui/lst/etn/ULDSTF08036.xml";            // 관리종목지정 우려 예고 등록 팝업 (원본 ../etn/ULDSTF08036.gfm — 경로 가정, 결과서 §10 #5)
scwin.POPUP_URL_REG_NEW = "/ui/lst/etn/ULDSTF08036_new.xml";    // 같은 팝업의 발행회사 기준 신규판 (원본 ../etn/ULDSTF08036_new.gfm — 경로 가정)
scwin.searchTp = "1";       // 현재 조회 구분 (SEARCH_TP_ISU · SEARCH_TP_ISUR)
scwin.isurCd = "";          // 종목 찾기에서 고른 종목의 발행기관코드 (원본 vIsurCd)
scwin.listStatCd = "Y";     // 종목 찾기에서 고른 종목의 상장상태 — D 면 신규·수정 금지 (원본 vLIST_STAT_CD)

// 원본 : /etn/ULDSTF08035.gfm (ETN 관리종목지정 우려예고)
/*
 * 화면 동작
 *  - [종목] 또는 [발행회사] 중 하나를 골라 ETN 관리종목지정 우려예고 내역을 조회한다.
 *    종목은 [종목 찾기]로 고른 뒤 [조회], 발행회사는 라디오를 고르거나 콤보를 바꾸면 바로 조회한다.
 *  - [신규]는 등록 팝업(종목 기준 ULDSTF08036 / 발행회사 기준 ULDSTF08036_new)을, 목록 더블클릭은 같은 팝업을 수정으로 연다.
 *  - 상장폐지(삭제) 종목을 고르면 [신규]를 막고, 종목 기준 목록 더블클릭도 막는다.
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF08035/ULDSTF08035.md (§번호는 이 문서의 절)
 */

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08035.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 로딩 — 조회 구분을 종목으로 두고 조회 영역 Enter 키를 바인딩한다. 자동 조회는 하지 않는다(원본과 같음). (원본 gform onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 조회 구분 종목 (원본 rdo_ISUR_CD_1.CodeValue = "1")
    scwin.changeSearchTp(scwin.SEARCH_TP_ISU);

    // 2) 조회 영역 Enter 키(규칙 22) — 입력란은 읽기 전용이지만 영역 포커스에서 조회한다
    $c.win.setEnterKeyEvent(pan_Cnd, scwin.btn_Search_onclick);

    // 3) 발행회사 콤보 — 원본 fn_get_isurcode(/etn/EtnCodeAct.do?method=listIsurCd&For=R)
    //    대응 API 가 명세에 없어 부르지 않는다 → 콤보는 "전체" 하나 (§10 #1)
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 버튼 클릭 (조회 영역 Enter 키도 이 핸들러) — 종목 기준이면 종목을 골랐는지 먼저 본다. (원본 img_Search onclick)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Search_onclick = async function (e) {
    try {
        if (!(await scwin.validateSearch())) return;
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08035.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.rdo_ISUR_CD_1_onviewchange
 * @author Inswave
 * @date 2026. 10. 30
 * @description [종목] 라디오 선택 — 조회 구분을 종목으로 바꾼다(발행회사 콤보는 전체로). 조회는 하지 않는다. (원본 rdo_ISUR_CD_1 OnClick → fn_changeRadioBtn(1))
 * @param {Object} info 변경 정보
 * @returns
 * @hidden N
 */
scwin.rdo_ISUR_CD_1_onviewchange = function (info) {
    try {
        scwin.changeSearchTp(scwin.SEARCH_TP_ISU);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08035.rdo_ISUR_CD_1_onviewchange" });
    }
};

/**
 * @method
 * @name scwin.rdo_ISUR_CD_2_onviewchange
 * @author Inswave
 * @date 2026. 10. 30
 * @description [발행회사] 라디오 선택 — 조회 구분을 발행회사로 바꾸고(종목 비움) 바로 조회한다. (원본 rdo_ISUR_CD_2 OnClick → fn_changeRadioBtn(2) · fn_search)
 * @param {Object} info 변경 정보
 * @returns
 * @hidden N
 */
scwin.rdo_ISUR_CD_2_onviewchange = async function (info) {
    try {
        scwin.changeSearchTp(scwin.SEARCH_TP_ISUR);
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08035.rdo_ISUR_CD_2_onviewchange" });
    }
};

/**
 * @method
 * @name scwin.cmb_ISUR_CD_onviewchange
 * @author Inswave
 * @date 2026. 10. 30
 * @description 발행회사 콤보 변경 — 조회 구분을 발행회사로 바꾸고 바로 조회한다. (원본 cmb_ISUR_CD OnSelChange → fn_changeRadioBtn(2) · fn_search)
 * @param {Object} info 변경 정보
 * @returns
 * @hidden N
 */
scwin.cmb_ISUR_CD_onviewchange = async function (info) {
    try {
        scwin.changeSearchTp(scwin.SEARCH_TP_ISUR);
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08035.cmb_ISUR_CD_onviewchange" });
    }
};

/**
 * @method
 * @name scwin.btn_iSU_CD_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목 찾기(돋보기) 버튼 클릭 (원본 btn_iSU_CD onclick → fn_PopFindEtnIsuAll + fn_SetParIsur)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_iSU_CD_onclick = async function (e) {
    try {
        await scwin.openIsuPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08035.btn_iSU_CD_onclick" });
    }
};

/**
 * @method
 * @name scwin.grd_List_oncelldblclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 목록 행 더블클릭 — 그 건을 등록 팝업(ULDSTF08036)으로 연다. (원본 grd_List OnDblClick)
 * @param {Number} rowIndex 행 인덱스(화면 번호)
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns
 * @hidden N
 */
scwin.grd_List_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.openDetail(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08035.grd_List_oncelldblclick" });
    }
};

/**
 * @method
 * @name scwin.img_Excel_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 엑셀다운로드 버튼 클릭 (원본 img_Excel onclick)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_Excel_onclick = async function (e) {
    try {
        await scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08035.img_Excel_onclick" });
    }
};

/**
 * @method
 * @name scwin.img_Regist_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 버튼 클릭 (원본 img_Regist onclick)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_Regist_onclick = async function (e) {
    try {
        await scwin.writeNew();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08035.img_Regist_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectListIsu
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목 기준 관리종목지정우려예고 목록 조회. (원본 fn_search — DIV_ETN_IDX_ADMISUNOTI_LIST_ISU, 명세 ② — §5.1)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectListIsu = async function () {
    const sbmOptions = {
        id : "sbm_selectListIsu",
        method : "get",
        action : "/api/listing/lstproc/etn/adm-isu-noti/select-list-isu",
        target : "dlt_list=body",
        gridview : "grd_List",
        isProcessMsg : false
    };

    // 명세 ② requestData { isuCd }
    const result = await $c.sbm.executeDynamic(sbmOptions, { isuCd : dma_search.get("isuCd") });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    return result.responseJSON?.success === true;    // 실패 안내는 공통 오류 핸들러(원본 OnLoadError → alert_error)
};

/**
 * @method
 * @name scwin.selectListCorp
 * @author Inswave
 * @date 2026. 10. 30
 * @description 발행회사 기준 관리종목지정우려예고 목록 조회 — 콤보가 "전체"면 발행기관코드를 빈 값으로 보낸다.
 * (원본 fn_search — 전체 DIV_ETN_IDX_ADMISUNOTI_LIST_ALL / 발행회사 DIV_ETN_IDX_ADMISUNOTI_LIST_CORP, 명세 ① — §5.2)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectListCorp = async function () {
    const sbmOptions = {
        id : "sbm_selectListCorp",
        method : "get",
        action : "/api/listing/lstproc/etn/adm-isu-noti/select-list-corp",
        target : "dlt_list=body",
        gridview : "grd_List",
        isProcessMsg : false
    };

    // 명세 ① requestData { isurCd }
    // TODO: 원본 "전체"(LIST_ALL, GUBUN_CD=ETN)에 대응하는 명세가 없다 — 빈 isurCd 를 전체로 받는지 확인 (§10 #2)
    const result = await $c.sbm.executeDynamic(sbmOptions, { isurCd : dma_search.get("isurCd") });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    return result.responseJSON?.success === true;    // 실패 안내는 공통 오류 핸들러
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 — 조회 구분에 따라 종목/발행회사 기준 목록을 조회하고 건수를 적은 뒤 마지막 행에 포커스한다.
 * (원본 fn_search + dts OnLoadCompleted — §6.1)
 * @returns
 * @hidden N
 */
scwin.search = async function () {
    // 조회 전 목록·건수를 비운다 — 조회가 실패하면 앞 조건의 행으로 팝업을 여는 일이 없도록
    dlt_list.removeAll();
    txb_TotCnt.setValue("0");

    const ok = (scwin.searchTp === scwin.SEARCH_TP_ISU) ? await scwin.selectListIsu() : await scwin.selectListCorp();
    if (!ok) return;

    const rowCount = dlt_list.getRowCount();
    txb_TotCnt.setValue(rowCount);      // 원본 txb_TotCnt.value = "총건수 : " + rowcount
    if (rowCount > 0) {
        grd_List.setFocusedCell(rowCount - 1, "isuNm");      // 원본 dts.RowPosition = rowcount
    }
};

/**
 * @method
 * @name scwin.validateSearch
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목 기준이면 종목을 골랐는지 본다. 안 골랐으면 MSG-0015 를 띄운다. (원본 img_Search·img_Regist onclick 의 공통 검사 — §6.1)
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
 */
scwin.validateSearch = async function () {
    if (scwin.searchTp === scwin.SEARCH_TP_ISU && $c.util.isEmpty(dma_search.get("isuCd"))) {
        // MSG-0015 "[종목코드(명)]을 선택해주세요."
        await $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
        btn_iSU_CD.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.changeSearchTp
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 구분을 바꾸고 두 라디오를 맞춘다. 종목으로 가면 발행회사 콤보를 전체로, 발행회사로 가면 종목을 비우고 상장상태를 풀어 [신규]를 다시 쓸 수 있게 한다.
 * (원본 fn_changeRadioBtn(idx) — §6.2, 상장상태 해제는 §8 #3)
 * @param {String} searchTp 조회 구분 (SEARCH_TP_ISU · SEARCH_TP_ISUR)
 * @returns
 * @hidden N
 */
scwin.changeSearchTp = function (searchTp) {
    scwin.searchTp = searchTp;

    if (searchTp === scwin.SEARCH_TP_ISU) {
        dma_search.set("isurCd", "");       // 원본 cmb_ISUR_CD.index = 0
        rdo_ISUR_CD_1.setValue("1");
        rdo_ISUR_CD_2.setValue("");
    } else {
        dma_search.set("isuCd", "");        // 원본 txb_ISU_CD·txb_ISU_NM 비움
        txb_ISU_NM.setValue("");
        scwin.isurCd = "";
        scwin.setListStat("Y");
        rdo_ISUR_CD_1.setValue("");
        rdo_ISUR_CD_2.setValue("1");
    }
};

/**
 * @method
 * @name scwin.setListStat
 * @author Inswave
 * @date 2026. 10. 30
 * @description 고른 종목의 상장상태를 기억하고, 상장폐지(D)면 [신규]를 막는다. (원본 fn_SetParIsur 의 img_Regist disabled — §6.3)
 * @param {String} listStatCd 상장상태코드
 * @returns
 * @hidden N
 */
scwin.setListStat = function (listStatCd) {
    scwin.listStatCd = listStatCd ?? "";
    img_Regist.setDisabled(scwin.listStatCd === scwin.LIST_STAT_DELISTED);
};

/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목 찾기(ULDSTF92017_1 상장·비상장 종목약명 조회) — 고른 종목으로 조회 구분을 종목으로 바꾸고 종목코드·약명·발행기관코드·상장상태를 채운 뒤 조회한다. 취소·닫기면 그대로 둔다.
 * (원본 fn_GetParIsur/fn_SetParIsur + fn_PopFindEtnIsuAll(ULDSTF92017_2) — §6.3·§6.5)
 * @returns
 * @hidden N
 */
scwin.openIsuPopup = async function () {
    // TODO: 원본 ETN 종목약명 찾기 ULDSTF92017_2 는 미전환 — 전환된 92017_1(같은 계열, secugrpId 로 거름)로 연다 (§10 #4)
    const result = await $c.lc.popFindIsuAll({ secugrpId : scwin.SECUGRP_ID_EN });

    // 취소·닫기(X)는 반환이 없거나 { isCloseButtonClick } — 종목코드로 판정한다
    if ($c.util.isEmpty(result?.isuCd)) return;

    scwin.changeSearchTp(scwin.SEARCH_TP_ISU);
    dma_search.set("isuCd", result.isuCd);
    txb_ISU_NM.setValue(result.isuKorAbbrv ?? "");      // 원본 arrPar[0].ISU_KOR_ABBRV
    scwin.isurCd = result.isurCd ?? "";                  // 원본 vIsurCd = arrPar[0].ISUR_CD
    scwin.setListStat(result.listStatCd);                // 원본 vLIST_STAT_CD = arrPar[0].LIST_STAT_CD

    await scwin.search();
};

/**
 * @method
 * @name scwin.getPopupData
 * @author Inswave
 * @date 2026. 10. 30
 * @description 등록 팝업(ULDSTF08036·08036_new)에 넘길 data. 신규는 업무처리번호·구분코드가 빈 값이고, 수정은 더블클릭한 행 값을 쓴다.
 * (원본 fn_GetParNew / fn_GetParUpdate 의 arrPar[0..7] — §6.4·§6.5)
 * @param {Number} rowIndex 수정할 행(화면 번호). 신규면 -1
 * @returns {Object} 넘길 data
 * @hidden N
 */
scwin.getPopupData = function (rowIndex) {
    const isNew = (rowIndex < 0);
    const data = {
        isurCd : "",                                        // arr[0] 발행기관코드
        isurNm : "",                                        // arr[1] 발행기관명(종목 기준이면 종목약명)
        secugrpId : scwin.SECUGRP_ID_EN,                    // arr[2] 증권그룹
        mktId : $c.session.getUserInfo("market"),           // arr[3] 시장구분 (원본 fn_getMktId() — 로그인 사용자 시장)
        bzProcsNo : isNew ? "" : dlt_list.getCellData(rowIndex, "bzProcsNo"),                  // arr[4] 업무처리번호 (신규는 없음)
        admisuDesignBzTpCd : isNew ? "" : dlt_list.getCellData(rowIndex, "admisuDesignBzTpCd"),  // arr[5] 관리종목지정및해제구분코드 (§10 #3)
        isuCd : "",                                         // arr[6] 종목코드
        selTp : ""                                          // arr[7] 선택 구분 1: 종목, 2: 발행회사, 3: 전체
    };

    if (scwin.searchTp === scwin.SEARCH_TP_ISU) {
        data.isurCd = isNew ? scwin.isurCd : dlt_list.getCellData(rowIndex, "isurCd");
        data.isurNm = txb_ISU_NM.getValue();
        data.isuCd = dma_search.get("isuCd");
        data.selTp = scwin.SEL_TP_ISU;
    } else if ($c.util.isEmpty(dma_search.get("isurCd"))) {
        // 발행회사 "전체" — 신규는 발행회사를 비워 넘기고, 수정은 행의 발행회사를 넘긴다
        data.isurCd = isNew ? "" : dlt_list.getCellData(rowIndex, "isurCd");
        data.isurNm = isNew ? "" : dlt_list.getCellData(rowIndex, "comNm");
        data.selTp = scwin.SEL_TP_ALL;
    } else {
        data.isurCd = isNew ? dma_search.get("isurCd") : dlt_list.getCellData(rowIndex, "isurCd");
        data.isurNm = isNew ? cmb_ISUR_CD.getText() : dlt_list.getCellData(rowIndex, "comNm");
        data.selTp = scwin.SEL_TP_ISUR;
    }
    return data;
};

/**
 * @method
 * @name scwin.openRegPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 등록 팝업을 data 로 열고 닫힐 때까지 기다린다. 저장했다고 돌려주거나 X 로 닫히면 목록을 다시 조회한다.
 * (원본 fn_new_create_frame / fn_newpre_create_frame — §6.4·§6.5)
 * @param {Boolean} isCorpNew 발행회사 기준 신규판(ULDSTF08036_new)을 열지 여부
 * @param {Object} data 넘길 data (scwin.getPopupData)
 * @returns
 * @hidden N
 */
scwin.openRegPopup = async function (isCorpNew, data) {
    const options = {
        id : isCorpNew ? "ULDSTF08036_new" : "ULDSTF08036",
        popupName : scwin.SECUGRP_NM_EN + " 관리종목지정 우려 예고",
        width : isCorpNew ? 750 : 720,
        height : 450,
        type : "pageFramePopup"
    };

    // TODO: ULDSTF08036·08036_new 는 미전환 — 경로·data 키·반환 { isSaved } 는 제안이다 (§10 #5)
    const result = await $c.win.openPopup(isCorpNew ? scwin.POPUP_URL_REG_NEW : scwin.POPUP_URL_REG, options, data);

    // 원본은 팝업이 닫혀도 이 화면이 다시 조회하지 않았다 — 저장 결과를 보이도록 다시 조회한다(§8 #4)
    if (result?.isSaved === true || result?.isCloseButtonClick === true) {
        await scwin.search();
    }
};

/**
 * @method
 * @name scwin.writeNew
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 — 종목 기준이면 종목을 골랐는지 보고, 발행회사 기준이면 발행회사 신규판(ULDSTF08036_new), 종목 기준이면 ULDSTF08036 을 연다. (원본 img_Regist onclick — §6.4)
 * @returns
 * @hidden N
 */
scwin.writeNew = async function () {
    if (!(await scwin.validateSearch())) return;
    await scwin.openRegPopup(scwin.searchTp === scwin.SEARCH_TP_ISUR, scwin.getPopupData(-1));
};

/**
 * @method
 * @name scwin.openDetail
 * @author Inswave
 * @date 2026. 10. 30
 * @description 수정 — 종목 기준에서 상장폐지 종목이면 아무것도 하지 않고, 아니면 그 행 값으로 ULDSTF08036 을 연다. (원본 grd_List OnDblClick — §6.4)
 * @param {Number} rowIndex 행 인덱스(화면 번호)
 * @returns
 * @hidden N
 */
scwin.openDetail = async function (rowIndex) {
    if (rowIndex < 0) return;
    // 삭제(상장폐지) 종목은 팝업 금지 (원본 jackal_11.05.12)
    if (scwin.searchTp === scwin.SEARCH_TP_ISU && scwin.listStatCd === scwin.LIST_STAT_DELISTED) return;

    await scwin.openRegPopup(false, scwin.getPopupData(rowIndex));
};

/**
 * @method
 * @name scwin.excelDown
 * @author Inswave
 * @date 2026. 10. 30
 * @description 목록을 엑셀로 내려받는다. 0건 안내는 공통 함수가 한다. (원본 GridToExcel(… "괸리종목지정 우려 예고 내역", "", "8"), doLogSave 삭제 — §6.6)
 * @returns
 * @hidden N
 */
scwin.excelDown = async function () {
    await $c.data.downloadGridViewExcel(grd_List, {
        // 파일명 {menuId}_{이름}_{yyyyMMddHHmmss}.xlsx (전환 규칙 42)
        fileName : $c.win.getProgramId() + "_" + scwin.SECUGRP_NM_EN + "관리종목지정우려예고내역_" + $c.date.getServerDateTime("yyyyMMddHHmmss") + ".xlsx",
        sheetName : "sheet1"
    });
};
